function f(o){if(!Number.isFinite(o)||o<0)return"";const i=["角","分"],c=["零","壹","贰","叁","肆","伍","陆","柒","捌","玖"],l=[["元","万","亿"],["","拾","佰","仟"]];let e=o,r="";for(let t=0;t<i.length;t+=1)r+=(c[Math.floor(e*10*Math.pow(10,t))%10]+i[t]).replace(/零./,"");r=r||"整",e=Math.floor(e);for(let t=0;t<l[0].length&&e>0;t+=1){let n="";for(let a=0;a<l[1].length&&e>0;a+=1)n=c[e%10]+l[1][a]+n,e=Math.floor(e/10);r=n.replace(/(零.)*零$/,"").replace(/^$/,"零")+l[0][t]+r}return r.replace(/(零.)*零元/,"元").replace(/(零.)+/g,"零").replace(/^整$/,"零元整")}export{f as a};
